<?php
const UNIT_NOTE='Satuan mengikuti sumber SIPSN (tidak tertera di file; umumnya ton/hari dan ton/tahun). Kode periode ditampilkan apa adanya.';
function nf($n,$d=0){return number_format((float)$n,$d,',','.');}
function sipsn_ensure(){global $db;$db->exec("CREATE TABLE IF NOT EXISTS waste_generation_sipsn(id INT AUTO_INCREMENT PRIMARY KEY,tahun SMALLINT NOT NULL,periode VARCHAR(10) NOT NULL,nama_provinsi VARCHAR(60) NOT NULL,nama_kabkota VARCHAR(80) NOT NULL,jml_timbulan_harian DECIMAL(14,4) NOT NULL,jml_timbulan_tahun DECIMAL(16,4) NOT NULL,imported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq(tahun,periode,nama_kabkota))");
$db->exec("CREATE TABLE IF NOT EXISTS sipsn_imports(id INT AUTO_INCREMENT PRIMARY KEY,source VARCHAR(150),rows_read INT,rows_saved INT,rows_rejected INT,user_id INT NULL,imported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");}
function sipsn_upsert($rows){global $db;$st=$db->prepare('INSERT INTO waste_generation_sipsn(tahun,periode,nama_provinsi,nama_kabkota,jml_timbulan_harian,jml_timbulan_tahun) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE nama_provinsi=VALUES(nama_provinsi),jml_timbulan_harian=VALUES(jml_timbulan_harian),jml_timbulan_tahun=VALUES(jml_timbulan_tahun)');foreach($rows as $r)$st->execute($r);}
function sipsn_kpi(){try{sipsn_ensure();$y=q('SELECT MAX(tahun) y FROM waste_generation_sipsn')->fetch()['y'];if(!$y)return null;$r=q('SELECT SUM(jml_timbulan_harian) h,SUM(jml_timbulan_tahun) t,COUNT(DISTINCT nama_kabkota) n FROM waste_generation_sipsn WHERE tahun=?',[$y])->fetch();$r['all']=q('SELECT COUNT(DISTINCT nama_kabkota) c FROM waste_generation_sipsn')->fetch()['c'];return ['y'=>$y]+$r;}catch(Exception $x){return null;}}
function sipsn_insights($yr){$o=[];$r=q('SELECT nama_kabkota k,SUM(jml_timbulan_tahun) t FROM waste_generation_sipsn WHERE tahun=? GROUP BY nama_kabkota ORDER BY t DESC',[$yr])->fetchAll();if(!$r)return $o;$tot=array_sum(array_column($r,'t'));
$o[]=['ok','Timbulan tertinggi '.$yr,$r[0]['k'].': '.nf($r[0]['t']).' per tahun, '.nf($r[0]['t']/$tot*100,1).'% dari total '.count($r).' kab/kota yang terdata pada tahun ini.'];
$p=q('SELECT a.nama_kabkota k,a.jml_timbulan_tahun x,b.jml_timbulan_tahun y FROM waste_generation_sipsn a JOIN waste_generation_sipsn b ON b.nama_kabkota=a.nama_kabkota AND b.periode=a.periode AND b.tahun=a.tahun+1 WHERE b.tahun=? AND a.jml_timbulan_tahun>0',[$yr])->fetchAll();$cu=0;
if($p){usort($p,fn($a,$b)=>($b['y']/$b['x'])<=>($a['y']/$a['x']));$u=$p[0];$d=end($p);$cu=($u['y']/$u['x']-1)*100;$cd=($d['y']/$d['x']-1)*100;$sx=array_sum(array_column($p,'x'));$sy=array_sum(array_column($p,'y'));
$o[]=['warn','Perubahan vs '.($yr-1).' (wilayah sebanding)','Naik terbesar: '.$u['k'].' ('.nf($cu,1).'%). '.($d['k']!=$u['k']?'Turun/naik terkecil: '.$d['k'].' ('.nf($cd,1).'%). ':'').'Total '.count($p).' wilayah yang ada di kedua tahun berubah '.nf(($sy/$sx-1)*100,1).'%.'];}
else $o[]=['info','Perbandingan tahunan','Belum ada wilayah yang datanya tersedia pada '.($yr-1).' dan '.$yr.', sehingga perubahan tidak dihitung.'];
$c=q('SELECT tahun,COUNT(DISTINCT nama_kabkota) n FROM waste_generation_sipsn GROUP BY tahun ORDER BY tahun')->fetchAll();$ns=array_column($c,'n');
if(min($ns)!=max($ns))$o[]=['warn','Cakupan data tidak seragam','Jumlah kab/kota terdata per tahun: '.implode(', ',array_map(fn($x)=>$x['tahun'].': '.$x['n'],$c)).'. Total antartahun tidak setara, jadi gunakan perubahan wilayah sebanding.'];
$top=array_slice($r,0,3);$o[]=['info','Rekomendasi prioritas','Prioritaskan pengelolaan sampah di '.implode(', ',array_column($top,'k')).', yang menyumbang '.nf(array_sum(array_column($top,'t'))/$tot*100,1).'% dari total terdata '.$yr.'.'.($p&&$cu>5?' Pantau juga '.$p[0]['k'].' yang naik '.nf($cu,1).'%.':'')];
return $o;}
